arguments.content:
"""Gerador procedural de labirintos para "Viriato's Maze".

A grelha tem 36 linhas x 28 colunas; ``0`` é corredor (transitável) e
``1`` é parede.  Para qualquer seed o labirinto respeita:

* dimensões exatas (36 x 28) e bordadura de parede, com a exceção dos
  dois extremos (coluna 0 e coluna 27) de uma única linha de túnel
  wrap-around esquerda–direita;
* simetria em espelho no eixo vertical: ``grid[r][c] == grid[r][27-c]``;
* sem dead ends: todo corredor tem 2 ou mais vizinhos de corredor na
  vizinhança de 4 (nas células do túnel, a célula oposta conta como
  vizinha pelo wrap-around);
* uma única componente conexa de corredor (vizinhança de 4);
* castrum: bloco sólido de parede de 6x4 (linhas 15-18, colunas 11-16),
  horizontalmente centrado e sempre rodeado de corredor;
* densidade de corredor entre 35% e 60% da grelha;
* determinismo: a mesma seed dá sempre a mesma grelha.

Apenas standard library é usada.
"""

from __future__ import annotations

import random

ROWS = 36
COLS = 28

# Castrum: 4 linhas x 6 colunas, colunas 11-16, linhas 15-18.
CASTRUM_ROWS = (15, 16, 17, 18)
CASTRUM_COLS = (11, 12, 13, 14, 15, 16)

# Meta de densidade de corredor (bem dentro do intervalo pedido, 35%-60%).
MIN_OPEN_FRACTION = 0.45
MAX_OPEN_FRACTION = 0.60


def _neighborhood(r: int, c: int, tunnel_row: int) -> list[tuple[int, int]]:
    """Vizinhança de 4, com wrap-around na linha do túnel (col 0 <-> col 27)."""
    out: list[tuple[int, int]] = []
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < ROWS and 0 <= nc < COLS:
            out.append((nr, nc))
        elif tunnel_row is not None and r == tunnel_row and dr == 0:
            # Túnel lateral: saír por uma extremidade aparece na outra.
            if c == 0 and dc == -1:
                out.append((r, COLS - 1))
            elif c == COLS - 1 and dc == 1:
                out.append((r, 0))
    return out


def _protected_cells() -> set[tuple[int, int]]:
    """Células que nunca podem ser mudadas (bordadura, castrum e o seu aro)."""
    prot: set[tuple[int, int]] = set()
    for r in range(ROWS):
        prot.add((r, 0))
        prot.add((r, COLS - 1))
    for c in range(COLS):
        prot.add((0, c))
        prot.add((ROWS - 1, c))
    # Castrum: bloco sólido 6x4.
    for r in CASTRUM_ROWS:
        for c in CASTRUM_COLS:
            prot.add((r, c))
    # Aro de corredor à volta do castrum (todos os lados).
    for c in CASTRUM_COLS:
        prot.add((r - 1 := 14, c))
        prot.add((19, c))
    for r in CASTRUM_ROWS:
        prot.add((r, CASTRUM_COLS[0] - 1))   # coluna 10
        prot.add((r, CASTRUM_COLS[-1] + 1))  # coluna 17
    return prot


def _candidate_ok(grid, cell, walls, tunnel_row, protected) -> bool:
    """Uma célula de corredor (ou uma que passa a parede) mantém >= 2 saídas?"""
    r, c = cell
    if grid[r][c] != 0 or cell in walls:
        return True  # já era parede, ou torna-se parede
    open_neigh = 0
    for nr, nc in _neighborhood(r, c, tunnel_row):
        if grid[nr][nc] == 0 and (nr, nc) not in walls:
            open_neigh += 1
    return open_neigh >= 2


def _still_connected(grid, walls, tunnel_row, target_open) -> bool:
    """Todos os corredores restantes alcançam a célula do túnel?"""
    start = (tunnel_row, 0)
    if start in walls:
        return False
    seen = {start}
    stack = [start]
    while stack:
        cr, cc = stack.pop()
        for nr, nc in _neighborhood(cr, cc, tunnel_row):
            if grid[nr][nc] == 0 and (nr, nc) not in walls and (nr, nc) not in seen:
                seen.add((nr, nc))
                stack.append((nr, nc))
    return len(seen) == target_open


def _try_generate(rng: random.Random) -> list[list[int]] | None:
    # Ponto de partida: interior todo corredor (grelha de malha, sem dead ends,
    # uma única componente), bordadura de parede, castrum já desenhado.
    grid = [[1] * COLS for _ in range(ROWS)]
    for r in range(1, ROWS - 1):
        for c in range(1, COLS - 1):
            grid[r][c] = 0

    protected = _protected_cells()
    for r in CASTRUM_ROWS:
        for c in CASTRUM_COLS:
            grid[r][c] = 1

    # Túnel: uma única linha (fora do castrum) onde col 0 e col 27 são corredor.
    tunnel_row = rng.choice(
        [r for r in range(1, ROWS - 1) if r not in CASTRUM_ROWS]
    )
    grid[tunnel_row][0] = 0
    grid[tunnel_row][COLS - 1] = 0

    total = ROWS * COLS
    open_count = sum(1 for r in range(ROWS) for c in range(COLS) if grid[r][c] == 0)
    target = int(total * rng.uniform(0.46, 0.56))

    # Células onde se pode acrescentar parede (interior, protegido e castrum fora).
    pool = [
        (r, c)
        for r in range(1, ROWS - 1)
        for c in range(1, COLS - 1)
        if grid[r][c] == 0 and (r, c) not in protected
    ]

    def is_valid(walls: set[tuple[int, int]], new_open: int) -> bool:
        # 1) Nenhum corredor vizinho das novas paredes fica com < 2 saídas.
        affected = set()
        for cr, cc in walls:
            affected.add((cr, cc))
            affected.update(_neighborhood(cr, cc, tunnel_row))
        for cell in affected:
            r, c = cell
            if grid[r][c] == 0 and cell not in walls:
                open_neigh = sum(
                    1
                    for nr, nc in _neighborhood(r, c, tunnel_row)
                    if grid[nr][nc] == 0 and (nr, nc) not in walls
                )
                if open_neigh < 2:
                    return False
        # 2) O corredor continua uma única componente.
        return _still_connected(grid, walls, tunnel_row, new_open)

    i = 0
    while i < len(pool) and open_count > target:
        r, c = pool[i]

        # Crescer um segmento de parede (de 2 a 6 células) para um aspeto
        # mais "de labirinto", em vez de ruído aleatório.
        cluster = {(r, c)}
        dr, dc = rng.choice(((-1, 0), (1, 0), (0, -1), (0, 1)))
        for _ in range(rng.randint(2, 6) - 1):
            cr, cc = cluster and (
                cluster.pop() or (r, c)
            )
            cluster.add((cr, cc))
            nr, nc = cr + dr, cc + dc
            if (
                not (1 <= nr <= ROWS - 2 and 1 <= nc <= COLS - 2)
                or (nr, nc) in protected
                or (nr, nc) in cluster
                or grid[nr][nc] == 1
            ):
                break
            cluster.add((nr, nc))

        # A simetria em espelho é imposta no momento de gravar a parede.
        walls = set()
        for cr, cc in cluster:
            walls.add((cr, cc))
            walls.add((cr, COLS - 1 - cc))

        if not is_valid(walls, open_count - len(walls)):
            # Fica a tentar apenas o par simétrico mínimo; se ainda assim
            # falhar, esta célula nunca poderá ser parede (monotonia: mais
            # paredes só piora as condições), logo é descartada.
            single = {(r, c), (r, COLS - 1 - c)}
            if is_valid(single, open_count - len(single)):
                walls = single
            else:
                pool = pool[:i] + pool[i + 1:]
                continue

        walls_to_remove = set()
        for wr, wc in walls:
            grid[wr][wc] = 1
            walls_to_remove.add((wr, wc))
        open_count -= len(walls)
        pool = [p for p in pool if p not in walls_to_remove]
        if i >= len(pool):
            i = max(len(pool) - 1, 0)

    # Controlo final: densidade dentro do intervalo pedido.
    fraction = open_count / total
    if not (MIN_OPEN_FRACTION <= fraction <= MAX_OPEN_FRACTION):
        return None
    return grid


def generate_maze(seed: int) -> list[list[int]]:
    """Devolve uma grelha 36 linhas x 28 colunas.
    0 = corredor (transitável), 1 = parede.
    """
    # O laço de repetição é determinístico: a mesma seed refaz sempre as
    # mesmas tentativas (e só as usa se a primeira falhar).
    for attempt in range(32):
        rng = random.Random(seed * 1_000_003 + 7 * attempt)
        grid = _try_generate(rng)
        if grid is not None:
            return grid
    raise RuntimeError(f"falha ao gerar labirinto para seed={seed}")


def render(grid: list[list[int]]) -> str:
    """Devolva a grelha como texto ASCII: '#' parede, espaço corredor."""
    return "\n".join(
        "".join("#" if cell else " " for cell in row) for row in grid
    )


if __name__ == "__main__":
    print(render(generate_maze(1)))

