"""Valida o gerador de labirintos de maze.py contra todas as restrições."""
import maze


def neighborhood(g, r, c, tr):
    out = [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
    if r == tr:
        if c == 0:
            out[-1] = (r, 27)
        if c == 27:
            out[2] = (r, 0)
    return [(a, b) for a, b in out if 0 <= a < 36 and 0 <= b < 28]


def check(seed):
    g = maze.generate_maze(seed)

    # 1. dimensões
    assert len(g) == 36 and all(len(row) == 28 for row in g)
    assert all(v in (0, 1) for row in g for v in row)

    # 3. simetria em espelho
    for r in range(36):
        for c in range(28):
            assert g[r][c] == g[r][27 - c], (r, c)

    # 2 & 6. bordadura + exatamente uma linha de túnel fora do castrum
    tunnel_rows = [r for r in range(36) if g[r][0] == 0]
    assert len(tunnel_rows) == 1, tunnel_rows
    tr = tunnel_rows[0]
    assert g[tr][27] == 0
    assert tr not in (15, 16, 17, 18)
    assert all(v == 1 for v in g[0]) and all(v == 1 for v in g[35])
    for r in range(1, 35):
        expect = 0 if r == tr else 1
        assert g[r][0] == expect and g[r][27] == expect, r

    # 7. castrum 6x4 sólido, centrado, linhas 15-18, rodeado de corredor
    for r in range(15, 19):
        for c in range(11, 17):
            assert g[r][c] == 1, (r, c)
    ring = ([(14, c) for c in range(11, 17)] + [(19, c) for c in range(11, 17)]
            + [(r, 10) for r in range(15, 19)] + [(r, 17) for r in range(15, 19)])
    for r, c in ring:
        assert g[r][c] == 0, (r, c)

    # 8. sem dead ends (com wrap no túnel)
    for r in range(36):
        for c in range(28):
            if g[r][c] == 0:
                n = sum(1 for a, b in neighborhood(g, r, c, tr) if g[a][b] == 0)
                assert n >= 2, ("dead end", r, c, n)

    # 9. componente conexo único
    opens = [(r, c) for r in range(36) for c in range(28) if g[r][c] == 0]
    seen = {(tr, 0)}
    stack = [(tr, 0)]
    while stack:
        cr, cc = stack.pop()
        for a, b in neighborhood(g, cr, cc, tr):
            if g[a][b] == 0 and (a, b) not in seen:
                seen.add((a, b))
                stack.append((a, b))
    assert len(seen) == len(opens), (len(seen), len(opens))

    # densidade
    frac = len(opens) / (36 * 28)
    assert 0.35 < frac < 0.60, frac

    # 10. determinismo
    assert g == maze.generate_maze(seed)


def main():
    for seed in range(1, 41):
        check(seed)
    # seeds diferentes -> grelhas diferentes
    mazes = [maze.generate_maze(s) for s in range(1, 21)]
    for i in range(len(mazes)):
        for j in range(i + 1, len(mazes)):
            assert mazes[i] != mazes[j], (i, j)
    # render
    txt = maze.render(maze.generate_maze(1))
    lines = txt.split("\n")
    assert len(lines) == 36 and all(len(l) == 28 for l in lines)
    assert set("".join(lines)) <= {"#", " "}
    print("tudo OK: 40 seeds validadas, seeds distintas verificadas, render OK")


if __name__ == "__main__":
    main()

